def specialSequenceSize (D : ConstructionData 𝕜) {k : ℕ}
    (g : Fin k → C00 𝕜) (i : Fin k) : ℕ :=
  if i.val = 0 then D.j (2*k-1) else D.sigma (initialSegment g i)

