theorem SpecialSequence.size_averaged {D : ConstructionData 𝕜}
    {p : Seminorm 𝕜 (C00 𝕜)} {k : ℕ} {g : Fin k → C00 𝕜}
    (hg : SpecialSequence D p g) (i : Fin k) :
